#!/usr/bin/env python3
"""Bind manuscript-to-guide locators to a frozen traditional edition."""
from pathlib import Path
import argparse,hashlib,json,re
H=Path(__file__).resolve().parent
ap=argparse.ArgumentParser();ap.add_argument('--traditional',type=Path,default=H.parent/'traditional');a=ap.parse_args();T=a.traditional.resolve();tm=json.loads((T/'evidence/FINAL_PAGE_MAP.json').read_text());assert hashlib.sha256((T/tm['pdf']).read_bytes()).hexdigest()==tm['pdf_sha256']
aux=(H/'Paper_IX_Lean_Guide_Final.aux').read_text();labels={m[1]:int(m[2])for m in re.finditer(r'\\newlabel\{([^{}]+)\}\{\{[^{}]*\}\{([0-9]+)\}',aux)};cw=json.loads((H/'audit/CROSSWALK.json').read_text());names={'arithmetic':'Arithmetic','dyadic':'Reconstruction and dyadic results','foundations':'Exact coordinates','affine':'Affine obstructions','polynomial':'Polynomial digits and counts','towers':'Compatible towers','parameters':'Parameters and charts','weighted':'Weighted lifting and motion','regularity':'Analytic regularity'}
t=[r'\section{Manuscript-to-guide navigation}\label{sec:crosswalk}',r'The table pairs all 62 indexed statements with their number and physical PDF page in the final traditional paper, and a teaching destination in this guide. Guide locators use its printed page numbers. The paired JSON retains all 202 exact source links and both physical and printed guide locators.',r'{\footnotesize Traditional PDF SHA-256: \code{'+tm['pdf_sha256']+r'}.}\par',r'\begingroup\small',r'\begin{longtable}{p{.44\linewidth}r p{.27\linewidth}r}',r'\toprule Statement & Paper & Teaching chapter & Guide\\\midrule\endhead']
for r in cw:
 label=r['manuscript_label'];m=tm['labels'][label];r['traditional_pdf_sha256']=tm['pdf_sha256'];r['traditional_number']=m['number'];r['traditional_physical_page']=m['physical_page'];r['traditional_printed_page']=m['printed_page'];ch=r['guide_chapter'];r['guide_page']=labels['sec:'+ch];r['guide_printed_page']=labels['sec:'+ch];r['guide_physical_page']=labels['sec:'+ch]+1;t.append(r'\textbf{'+m['number']+'} '+r'\code{'+label+'} & '+str(m['physical_page'])+' & '+names[ch]+r' & \pageref{sec:'+ch+r'}\\')
m=tm['labels']['ex:arith-bernoulli'];t += [r'\textbf{'+m['number']+r'} \code{ex:arith-bernoulli} & '+str(m['physical_page'])+r' & Classical derivation; formal boundary & \pageref{sec:reading}\\',r'\bottomrule\end{longtable}\endgroup']
(H/'generated/crosswalk.tex').write_text('\n'.join(t)+'\n');(H/'audit/CROSSWALK.json').write_text(json.dumps(cw,indent=2)+'\n');print('PASS:62statementlocators/202source links pinned to final traditional PDF.')
